// Generated by dazl/scripts/dazl-in-dazl/install.mjs — edit the installer, not this file.
// Brings the embedded Postgres cluster up (creating it from nothing when the data dir is gone).
// Exits 0 when Postgres accepts connections on 5432. Never loops; a failure is reported once.
import fs from 'node:fs';
import path from 'node:path';
import url from 'node:url';
import net from 'node:net';
import { createRequire } from 'node:module';
import { spawnSync } from 'node:child_process';

const here = path.dirname(url.fileURLToPath(import.meta.url));
const ROOT = path.resolve(here, '..', '..');
const API = path.join(ROOT, 'api-server');
const databaseDir = path.join(here, '.local-pg'); // always dazl-setup/api-server/.local-pg
const PORT = 5432;
const USER = 'dazlapp';
const PASSWORD = 'password';

// the package lives in the app repo, this script does not — resolve it explicitly
const require = createRequire(path.join(API, 'package.json'));
const platformPkg = `@embedded-postgres/${process.platform}-${process.arch}`;
// the platform package's `exports` hides package.json from require.resolve, so locate it by path
const PGBIN = path.join(API, 'node_modules', platformPkg, 'native', 'bin');
if (!fs.existsSync(path.join(PGBIN, 'pg_ctl'))) {
    console.error(`[ensure-postgres] ${PGBIN}/pg_ctl missing; run the installer's api-deps step`);
    process.exit(1);
}

const portOpen = (port) =>
    new Promise((resolve) => {
        const s = net.connect({ port, host: '127.0.0.1' });
        s.once('connect', () => { s.destroy(); resolve(true); });
        s.once('error', () => resolve(false));
        s.setTimeout(1500, () => { s.destroy(); resolve(false); });
    });

const sh = (cmd, args, opts = {}) => {
    const r = spawnSync(cmd, args, { encoding: 'utf8', env: { ...process.env, LC_ALL: 'C' }, ...opts });
    if (r.stdout) process.stdout.write(r.stdout);
    if (r.stderr) process.stderr.write(r.stderr);
    return r.status;
};

async function main() {
    if (await portOpen(PORT)) {
        console.log(`[ensure-postgres] something already listens on ${PORT}; assuming the cluster is up`);
        return 0;
    }
    if (!fs.existsSync(path.join(databaseDir, 'PG_VERSION'))) {
        console.log(`[ensure-postgres] no cluster at ${databaseDir}; running initdb`);
        fs.rmSync(databaseDir, { recursive: true, force: true });
        const { default: EmbeddedPostgres } = await import(require.resolve('embedded-postgres'));
        const pg = new EmbeddedPostgres({ databaseDir, user: USER, password: PASSWORD, port: PORT, persistent: true });
        await pg.initialise();
        // hydrate-symlinks.js runs in the postinstall npm 11 defers; initialise() ran so binaries work.
    }
    const pidFile = path.join(databaseDir, 'postmaster.pid');
    if (fs.existsSync(pidFile)) {
        const pid = Number(fs.readFileSync(pidFile, 'utf8').split('\n')[0]);
        let alive = false;
        try { process.kill(pid, 0); alive = true; } catch {}
        if (!alive) { console.log('[ensure-postgres] removing stale postmaster.pid'); fs.rmSync(pidFile); }
    }
    // pg_ctl daemonises and returns, so the server outlives this script (process.exit would kill an
    // EmbeddedPostgres.start() child).
    const status = sh(path.join(PGBIN, 'pg_ctl'), ['-D', databaseDir, '-l', path.join(databaseDir, 'logfile'), '-o', `-p ${PORT} -k /tmp`, '-w', '-t', '60', 'start']);
    if (status !== 0) {
        const logfile = path.join(databaseDir, 'logfile');
        if (fs.existsSync(logfile)) console.error(fs.readFileSync(logfile, 'utf8').split('\n').slice(-30).join('\n'));
        console.error(`[ensure-postgres] pg_ctl start exited ${status}`);
        return 1;
    }
    for (let i = 0; i < 30 && !(await portOpen(PORT)); i++) await new Promise((r) => setTimeout(r, 1000));
    if (!(await portOpen(PORT))) { console.error('[ensure-postgres] started but port never opened'); return 1; }
    console.log('[ensure-postgres] postgres is accepting connections');
    return 0;
}

main().then((code) => process.exit(code), (err) => { console.error('[ensure-postgres] ' + (err?.stack ?? err)); process.exit(1); });
